import { useEffect, useState } from 'react';
import { ModelsTable } from './ModelsAndStorage';
import { Section } from './blocks';

interface PackageLicense {
  name: string;
  version: string;
  license: string;
  homepage: string | null;
  text: string;
}

/** Third-party open-source software and AI models used by Studiolo, with their license texts. */
export function Licenses() {
  const [list, setList] = useState<PackageLicense[] | null>(null);
  useEffect(() => {
    // Generated by scripts/gen-licenses.mjs at build time; loaded only on this page.
    void import('./licenses.json').then((m) => setList(m.default as PackageLicense[]));
  }, []);

  const groups = list ? Object.entries(list.reduce<Record<string, number>>((acc, p) => ((acc[p.license] = (acc[p.license] ?? 0) + 1), acc), {})).sort((a, b) => b[1] - a[1]) : [];

  return (
    <>
      <Section id="overview" title="Built with open source">
        <p>
          Studiolo is built on open-source software created and shared by many people. This page lists every third-party package included in the website, with its
          license, as those licenses require.
        </p>
        {list && (
          <p>
            {list.length} packages:{' '}
            {groups.map(([license, n], i) => (
              <span key={license}>
                {i > 0 && ', '}
                {n} {license}
              </span>
            ))}
            .
          </p>
        )}
      </Section>

      <Section id="models" title="AI models">
        <p>
          The AI tools download model weights from Hugging Face the first time you use them. The models are not part of this website and keep their own licenses:
        </p>
        <ModelsTable />
      </Section>

      <Section id="packages" title="Software packages">
        {!list && <p>Loading…</p>}
        <div className="flex flex-col gap-2">
          {list?.map((p) => (
            <details key={`${p.name}@${p.version}`} className="group rounded-[10px] border border-line bg-panel">
              <summary className="flex cursor-pointer list-none items-center gap-3 px-3.5 py-2.5 text-sm">
                <span className="min-w-0 flex-1 truncate font-medium text-fg">{p.name}</span>
                <span className="text-xs text-subtle tabular-nums">{p.version}</span>
                <span className="rounded-[5px] bg-control px-1.5 py-0.5 text-2xs font-medium text-muted">{p.license}</span>
              </summary>
              <div className="flex flex-col gap-2 border-t border-line px-3.5 py-3">
                {p.homepage && (
                  <a href={p.homepage} target="_blank" rel="noreferrer" className="w-fit text-xs text-accent hover:underline">
                    {p.homepage}
                  </a>
                )}
                {p.text ? (
                  <pre className="scroll-thin max-h-[320px] overflow-auto font-mono text-[length:calc(11px*var(--text-scale))] leading-[16px] whitespace-pre-wrap text-muted">{p.text}</pre>
                ) : (
                  <p className="text-xs text-subtle">This package doesn’t include a license file. It is published under the {p.license} license; see its homepage for details.</p>
                )}
              </div>
            </details>
          ))}
        </div>
      </Section>
    </>
  );
}
